import * as THREE from './vendor/three.module.js?revision=120';
// Botanical silhouettes: whorls, basal rosettes, flower heads, reed panicles and segmented succulent shoots.
export const WIND_FLOWERS=new Set(['urtica_dioica','plantago_lanceolata','plantago_maritima','artemisia_maritima']);
export const hasNectarFlowers=s=>s.form==='flower'&&!WIND_FLOWERS.has(s.id);
export function botanicalGeometry(s){const pos=[],normal=[],color=[],flowerTargets=[],leaf=new THREE.Color(s.colors.leaf),flower=new THREE.Color(s.colors.flower),stem=new THREE.Color(s.colors.bark);function add(g,c,p=[0,0,0],scale=[1,1,1],rot=[0,0,0]){const t=g.toNonIndexed(),m=new THREE.Matrix4().compose(new THREE.Vector3(...p),new THREE.Quaternion().setFromEuler(new THREE.Euler(...rot)),new THREE.Vector3(...scale));t.applyMatrix4(m);for(let i=0;i<t.attributes.position.array.length;i+=3){pos.push(...t.attributes.position.array.slice(i,i+3));normal.push(...t.attributes.normal.array.slice(i,i+3));color.push(c.r,c.g,c.b);}t.dispose();}
 const sphere=new THREE.SphereGeometry(1,6,4),tube=new THREE.CylinderGeometry(1,1,1,4),blade=new THREE.PlaneGeometry(1,1,1,2);const id=s.id;
 function stalk(x,z,h=1,w=.012){add(tube,stem,[x,h*.5-.48,z],[w,h,w]);}
 function bladeAt(x,y,z,l,w,a,tilt=.5){const g=curvedLeaf(l,w,false,s.form==='flower');add(g,leaf,[x,y-.48,z],[1,1,1],[tilt,a,0]);g.dispose();}
 function petals(x,y,z,number,radius,c=flower){flowerTargets.push([x,y-.48,z]);const poppy=id==='papaver_rhoeas';add(sphere,new THREE.Color(poppy?'#343327':'#c0a844'),[x,y-.472,z],[radius*.30,radius*.13,radius*.30]);const g=curvedLeaf(radius*.98,radius*(poppy?1.15:.48),true);
  for(let i=0;i<number;i++){const a=i*Math.PI*2/number,q=new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3(Math.cos(a),.13,Math.sin(a)).normalize()),e=new THREE.Euler().setFromQuaternion(q);add(g,c,[x+Math.cos(a)*radius*.10,y-.48,z+Math.sin(a)*radius*.10],[1,1,1],[e.x,e.y,e.z]);}
  g.dispose();
 }
 if(s.type==='grass'){for(let k=0;k<13;k++){const a=k*2.4;bladeAt(Math.cos(a)*.035,0,Math.sin(a)*.035,.55+(k%4)*.12,id==='ammophila_arenaria'?.018:.013,a,id==='ammophila_arenaria'?.19:.32);}stalk(0,0,1,.003);const dry=new THREE.Color('#abac80');if(id==='triticum_aestivum'||id==='elymus_athericus'){for(let k=0;k<9;k++)for(const side of [-1,1])add(sphere,dry,[side*.016,.31+k*.022,0],[.022,.016,.009],[0,0,side*.5]);}else if(id==='alopecurus_pratensis'||id==='ammophila_arenaria'){add(tube,dry,[0,.42,0],[.011,.16,.011]);}else for(let j=0;j<6;j++)for(let k=0;k<3;k++){const a=k*2.1+j*.8,r=(id==='poa_pratensis'?.095:.055)*(1-j/7),h=.7+j*.05;add(tube,dry,[Math.cos(a)*r*.5,h-.48,Math.sin(a)*r*.5],[.0015,r,.0015],[Math.sin(a)*.8,0,-Math.cos(a)*.8]);add(sphere,dry,[Math.cos(a)*r,h-.48,Math.sin(a)*r],[id==='dactylis_glomerata'?.018:.006,.018,.006]);}}
 else if(s.type==='moss'){for(let j=0;j<19;j++){const a=j*2.4,r=.035*Math.sqrt(j),x=Math.cos(a)*r,z=Math.sin(a)*r,h=.4+(j%5)*.08;stalk(x,z,h,.007);for(let k=0;k<12;k++)bladeAt(x,k*h/12,z,.09,.02,k*2.4,.9);}}
 else if(id==='atriplex_portulacoides'){stalk(0,0,.9,.016);for(let j=0;j<6;j++)for(const side of [-1,1]){const x=side*.08;stalk(x,0,.4+j*.07,.011);bladeAt(x,.12+j*.095,0,.18,.095,j*1.5+(side>0?0:Math.PI),.8);}}
 else if(id==='tripolium_pannonicum'){stalk(0,0,1,.015);for(let j=0;j<4;j++)bladeAt(0,j*.16,0,.27,.075,j*2.4,.85);for(let j=0;j<6;j++){const a=j*2.4;petals(Math.cos(a)*.12,.76+j*.035,Math.sin(a)*.12,10,.065);}}
 else if(id==='armeria_maritima'){for(let k=0;k<14;k++)bladeAt(0,0,0,.24,.018,k*2.4,.35);stalk(0,0,1,.007);for(let k=0;k<14;k++)petals(Math.cos(k*2.4)*.075,.90+Math.sin(k)*.04,Math.sin(k*2.4)*.075,5,.034);}
 else if(s.form==='queller'){for(let k=0;k<6;k++){const a=k*2.4,x=Math.cos(a)*.11,z=Math.sin(a)*.11,h=.4+k*.07;for(let j=0;j<5;j++)add(sphere,leaf,[x+j*.023*Math.cos(a),h*j/5-.48,z+j*.023*Math.sin(a)],[.025,.075,.025],[Math.sin(a)*.25,0,-Math.cos(a)*.25]);}}
 else if(s.type==='aquatic'&&id!=='nymphaea_alba'){for(let k=0;k<7;k++){const a=k*2.4;bladeAt(Math.cos(a)*.07,0,Math.sin(a)*.07,.7+.04*k,id.includes('zostera')?.04:.025,a,.15);}if(id==='ceratophyllum_demersum')for(let j=0;j<6;j++)for(let k=0;k<6;k++)bladeAt(0,j*.14,0,.18,.023,k*1.05,1.2);}
 else if(s.type==='reed'){stalk(0,0,1,.002);if(id==='typha_latifolia'){for(let k=0;k<7;k++)bladeAt(Math.cos(k*2.4)*.025,0,Math.sin(k*2.4)*.025,.9,.014,k*2.4,.12);add(tube,new THREE.Color('#574333'),[0,.4,0],[.011,.18,.011]);}else{for(let j=0;j<5;j++)bladeAt(0,.14+j*.13,0,.2,.014,j*2.4,.7);const dry=new THREE.Color('#9b9578');for(let j=0;j<6;j++)for(let k=0;k<3;k++){const a=k*2.1+j*.7,h=.74+j*.045,r=.075*(1-j/7);add(tube,dry,[Math.cos(a)*r*.5,h-.48,Math.sin(a)*r*.5],[.0012,r,.0012],[Math.sin(a)*.9,0,-Math.cos(a)*.9]);for(let n=0;n<3;n++)add(new THREE.ConeGeometry(1,1,4),dry,[Math.cos(a)*r,h-.48+n*.015,Math.sin(a)*r],[.004,.03,.004]);}}}
 else if(id==='nymphaea_alba'){for(let tier=0;tier<2;tier++)for(let k=0;k<12;k++){const a=k*6.28/12+tier*.24,r=tier?.10:.18;add(sphere,flower,[Math.cos(a)*r*.55,-.4+tier*.035,Math.sin(a)*r*.55],[r*.85,.018,.043],[0,-a,0]);}add(sphere,new THREE.Color('#c9ad4d'),[0,-.34,0],[.053,.018,.053]);}
 else if(id==='fomes_fomentarius'){add(new THREE.SphereGeometry(1,12,8,0,Math.PI),new THREE.Color('#9d9a87'),[0,0,0],[.5,.4,.35],[Math.PI/2,0,0]);for(let k=0;k<4;k++)add(new THREE.TorusGeometry(.42-k*.07,.013,3,12,Math.PI),new THREE.Color('#797969'),[0,.1-k*.05,.04],[1,.75,1],[0,0,0]);}
 else if(s.form==='plantain'||id==='plantago_lanceolata'||id==='plantago_maritima'){for(let k=0;k<8;k++)bladeAt(0,0,0,.6,.085,k*.78,1.05);for(let k=0;k<3;k++){const x=(k-1)*.1;stalk(x,0,.9,.008);add(sphere,new THREE.Color('#696550'),[x,.38,0],[.022,.11,.022]);for(let n=0;n<8;n++){const a=n*Math.PI/4;add(sphere,new THREE.Color('#ddd4b4'),[x+Math.cos(a)*.027,.34+(n%3)*.025,Math.sin(a)*.027],[.008,.005,.006]);}}}
 else if(id==='urtica_dioica'){stalk(0,0,1,.015);for(let j=0;j<4;j++)for(const side of [-1,1])bladeAt(0,.16+j*.2,0,.3,.17,j*1.5+(side>0?0:Math.PI),1.1);}
 else if(id==='galium_odoratum'){stalk(0,0,.9,.011);for(let j=0;j<3;j++)for(let k=0;k<7;k++)bladeAt(0,.18+j*.24,0,.22,.055,k*.9,1.3);for(let k=0;k<4;k++)petals(Math.cos(k*1.57)*.08,.94,Math.sin(k*1.57)*.08,4,.045);}
 else if(id==='trifolium_pratense'){flowerTargets.push([0,.4,0]);for(let k=0;k<3;k++){const a=k*2.1;stalk(Math.cos(a)*.07,Math.sin(a)*.07,.85,.013);for(let j=0;j<3;j++)bladeAt(0,.24,0,.19,.2,j*2.1,1.1);}add(sphere,flower,[0,.4,0],[.13,.13,.13]);for(let k=0;k<16;k++)add(sphere,flower,[Math.cos(k*2.4)*.11,.39+Math.sin(k)*.07,Math.sin(k*2.4)*.11],[.035,.045,.035]);}
 else if(id==='achillea_millefolium'||id==='limonium_vulgare'){stalk(0,0,1,.012);for(let k=0;k<5;k++)bladeAt(0,k*.14,0,.24,.065,k*2.4,.9);for(let k=0;k<9;k++){const a=k*2.4,r=.06+(k%3)*.05;petals(Math.cos(a)*r,1,Math.sin(a)*r,5,.04);}}
 else{stalk(0,0,1,.01);for(let k=0;k<5;k++)bladeAt(0,.1+k*.13,0,id==='anemone_nemorosa'?.19:.28,id==='centaurea_cyanus'?.055:.14,k*2.4,.8);petals(0,1,0,id==='papaver_rhoeas'?4:id.includes('maritimum')||id.includes('leucanthemum')?12:id==='centaurea_cyanus'?16:id==='anemone_nemorosa'?6:4,id==='papaver_rhoeas'?.16:.13);}
 const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normal,3));g.setAttribute('color',new THREE.Float32BufferAttribute(color,3));g.computeBoundingBox();if(s.type!=='fungus'&&s.id!=='nymphaea_alba'){const shift=-.48-g.boundingBox.min.y;g.translate(0,shift,0);flowerTargets.forEach(p=>p[1]+=shift);}g.userData.flowerTargets=flowerTargets;g.computeBoundingSphere();g.userData.botanicalSpecies=s.id;g.userData.flowering=s.form==='flower';sphere.dispose();tube.dispose();blade.dispose();return indexGeometry(g);}
